// @name Douyu Mini Library

const WidgetMetadata = {
  id: 'douyu-mini-library',
  name: '斗鱼直播',
  title: '斗鱼直播',
  version: '1.0.0',
  author: 'baiPlay',
  site: 'https://www.douyu.com/',
  logo: "data:image/png;base64,",
  icon: "data:image/png;base64,",
  description: '斗鱼直播自定义媒体库，支持分类、房间列表、搜索和房间卡片直接播放。'
};

const PC_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Safari/537.36 Edg/114.0.1823.43';
const MOBILE_UA = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';
const DOUYU_DID = '10000000000000000000000000001501';
const CACHE_TTL_MS = 30 * 60 * 1000;
const CATEGORY_CACHE_KEY = 'douyu:categories:v1';
const PLACEHOLDER_IMAGE = WidgetMetadata.logo;

const DEFAULT_HOME_CATEGORIES = [
  { cate1Id: 1, cate1Name: '网游竞技', shortName: 'PCgame' },
  { cate1Id: 15, cate1Name: '单机热游', shortName: 'djry' },
  { cate1Id: 9, cate1Name: '手游休闲', shortName: 'syxx' },
  { cate1Id: 2, cate1Name: '娱乐天地', shortName: 'yl' },
  { cate1Id: 8, cate1Name: '颜值', shortName: 'yz' },
  { cate1Id: 11, cate1Name: '科技文化', shortName: 'kjwh' },
  { cate1Id: 20, cate1Name: '语音互动', shortName: 'yp' },
  { cate1Id: 22, cate1Name: '赛车竞技', shortName: 'scjj' }
];

function getManifest() {
  return {
    id: WidgetMetadata.id,
    name: WidgetMetadata.name,
    title: WidgetMetadata.title,
    version: WidgetMetadata.version,
    author: WidgetMetadata.author,
    site: WidgetMetadata.site,
    description: WidgetMetadata.description,
    logo: WidgetMetadata.logo,
    icon: WidgetMetadata.icon,
    capabilities: {
      home: true,
      category: true,
      detail: true,
      search: true,
      resourceVersions: true,
      playback: true,
      aggregation: false,
      playbackHistory: true,
      resourceMatching: false
    },
    aggregation: {
      search: false,
      playbackHistory: true,
      resourceMatching: false
    },
    parameters: [
      {
        name: 'home_preview_limit',
        title: '首页每类预览数量',
        type: 'number',
        value: 10,
        description: '首页懒加载分类时最多展示多少个直播间。'
      },
      {
        name: 'prefer_format',
        title: '优先播放格式',
        type: 'enumeration',
        value: 'hls',
        enumOptions: [
          { title: 'HLS 优先', value: 'hls' },
          { title: 'FLV 优先', value: 'flv' }
        ]
      },
      {
        name: 'hevc',
        title: '请求 HEVC',
        type: 'boolean',
        value: false,
        description: '默认关闭，兼容性更好。'
      }
    ]
  };
}

function readConfig(ctx) {
  ctx = argsify(ctx);
  const params = ctx.params || ctx.config || ctx.settings || ctx.parameters || {};
  return {
    homePreviewLimit: clampNumber(params.home_preview_limit, 4, 20, 10),
    preferFormat: String(params.prefer_format || 'hls').toLowerCase() === 'flv' ? 'flv' : 'hls',
    hevc: parseBool(params.hevc)
  };
}

async function getHome(ctx = {}) {
  let categories = [];
  try {
    categories = (await loadCategories()).cate1Info;
  } catch (_) {
    categories = DEFAULT_HOME_CATEGORIES;
  }
  categories = categories.slice().sort((a, b) => Number(a.cate1Id || 0) - Number(b.cate1Id || 0));
  const topCategories = categories.slice(0, 8);
  return {
    pageType: 'home',
    id: 'douyu-home',
    title: WidgetMetadata.title,
    heroAspectRatio: '16:9',
    hero: [],
    sections: [
      {
        id: 'quick-categories',
        title: '直播分区',
        style: 'discover.annualWidePreview',
        subtitle: '按斗鱼分区浏览直播间',
        moreAction: { type: 'category', pageId: 'groups:all', title: '直播分区', itemAspectRatio: '16:9' },
        items: topCategories.map((category, index) => categoryEntry(category, index))
      }
    ].concat(topCategories.map((category) => ({
      id: 'home:' + category.cate1Id,
      title: category.cate1Name || '直播',
      style: 'discover.spotlight',
      subtitle: '正在直播',
      lazy: true,
      promotesToHero: Number(category.cate1Id) === Number(topCategories[0] && topCategories[0].cate1Id),
      moreAction: { type: 'category', pageId: 'cate1:' + category.cate1Id, title: category.cate1Name || '直播', itemAspectRatio: '16:9' },
      items: []
    })))
  };
}

async function getHomeSection(ctx = {}) {
  const config = readConfig(ctx);
  const sectionId = String(ctx.sectionId || ctx.id || '');
  if (sectionId.indexOf('home:') !== 0) {
    return {
      id: sectionId || 'unknown',
      title: ctx.title || '直播',
      style: ctx.style || 'discover.spotlight',
      lazy: false,
      items: []
    };
  }
  const cate1Id = sectionId.slice('home:'.length);
  try {
    const category = await findCate1(cate1Id);
    const subCategory = await firstSubCategory(cate1Id);
    const rooms = subCategory
      ? await fetchRoomsByCate2(subCategory.cate2Id, 1, config.homePreviewLimit)
      : await fetchRecommendRooms(1, config.homePreviewLimit);
    return {
      id: sectionId,
      title: ctx.title || category.cate1Name || '直播',
      style: ctx.style || 'discover.spotlight',
      subtitle: subCategory ? subCategory.cate2Name : '推荐直播',
      lazy: false,
      promotesToHero: !!ctx.promotesToHero,
      moreAction: { type: 'category', pageId: 'cate1:' + cate1Id, title: category.cate1Name || ctx.title || '直播', itemAspectRatio: '16:9' },
      items: rooms.map((room, index) => roomItem(room, index))
    };
  } catch (error) {
    return {
      id: sectionId,
      title: ctx.title || '直播',
      style: ctx.style || 'discover.spotlight',
      subtitle: '加载失败：' + errorMessage(error),
      lazy: false,
      items: []
    };
  }
}

async function getCategory(ctx = {}) {
  const pageId = String(ctx.pageId || ctx.id || 'groups:all');
  const page = Math.max(1, Number(ctx.page || 1));
  const pageSize = 40;

  if (pageId === 'groups:all') {
    const categories = await loadCategories();
    const entries = categories.cate1Info
      .slice()
      .sort((a, b) => Number(a.cate1Id || 0) - Number(b.cate1Id || 0))
      .map((category, index) => categoryEntry(category, index));
    return {
      pageType: 'category',
      id: pageId,
      title: ctx.title || '直播分区',
      style: 'discover.annualWidePreview',
      itemAspectRatio: '16:9',
      items: entries,
      page: 1,
      hasMore: false
    };
  }

  if (pageId.indexOf('cate1:') === 0) {
    const cate1Id = pageId.slice('cate1:'.length);
    const categories = await loadCategories();
    const cate1 = categories.cate1Info.find((item) => String(item.cate1Id) === cate1Id) || { cate1Name: ctx.title || '直播' };
    const subCategories = categories.cate2Info.filter((item) => String(item.cate1Id) === cate1Id);
    const start = (page - 1) * pageSize;
    const pageItems = subCategories.slice(start, start + pageSize);
    return {
      pageType: 'category',
      id: pageId,
      title: cate1.cate1Name || ctx.title || '直播分区',
      style: 'discover.annualWidePreview',
      itemAspectRatio: '16:9',
      items: pageItems.map((category, index) => subCategoryEntry(category, start + index)),
      page,
      hasMore: start + pageSize < subCategories.length
    };
  }

  if (pageId.indexOf('cate2:') === 0) {
    const cate2Id = pageId.slice('cate2:'.length);
    const rooms = await fetchRoomsByCate2(cate2Id, page, pageSize);
    return {
      pageType: 'category',
      id: pageId,
      title: ctx.title || '直播间',
      style: 'media.posterGrid',
      itemAspectRatio: '16:9',
      items: rooms.map((room, index) => roomItem(room, (page - 1) * pageSize + index)),
      page,
      hasMore: rooms.length >= pageSize
    };
  }

  if (pageId === 'recommend' || pageId === 'all') {
    const rooms = await fetchRecommendRooms(page, pageSize);
    return {
      pageType: 'category',
      id: pageId,
      title: ctx.title || '推荐直播',
      style: 'media.posterGrid',
      itemAspectRatio: '16:9',
      items: rooms.map((room, index) => roomItem(room, (page - 1) * pageSize + index)),
      page,
      hasMore: rooms.length >= pageSize
    };
  }

  return {
    pageType: 'category',
    id: pageId,
    title: ctx.title || '直播',
    style: 'media.posterGrid',
    itemAspectRatio: '16:9',
    items: [],
    page,
    hasMore: false
  };
}

async function search(ctx = {}) {
  const keyword = String(ctx.keyword || ctx.query || ctx.text || '').trim();
  const page = Math.max(1, Number(ctx.page || 1));
  if (!keyword) {
    return { pageType: 'search', title: '搜索斗鱼直播', keyword, page, hasMore: false, items: [] };
  }
  const pageSize = 20;
  const did = randomHex(32);
  const url = 'https://www.douyu.com/japi/search/api/searchShow?kw=' + encodeURIComponent(keyword) + '&page=' + page + '&pageSize=' + pageSize;
  const result = await requestJSON(url, {
    headers: Object.assign({}, defaultHeaders('https://www.douyu.com/search/'), {
      Cookie: 'dy_did=' + did + ';acf_did=' + did
    })
  });
  if (result && result.error && Number(result.error) !== 0) {
    throw new Error(result.msg || '斗鱼搜索失败');
  }
  const rooms = (((result || {}).data || {}).relateShow || []).map((item) => normalizeSearchRoom(item));
  return {
    pageType: 'search',
    title: '搜索斗鱼直播',
    keyword,
    page,
    hasMore: rooms.length >= pageSize,
    items: rooms.map((room, index) => roomItem(room, (page - 1) * pageSize + index))
  };
}

async function getDetail(ctx = {}) {
  const itemId = String(ctx.itemId || ctx.id || '').trim();
  const roomId = roomIdFromAny(itemId || ctx.url || ctx.href);
  if (!roomId) throw new Error('缺少斗鱼房间 ID');
  const room = await getRoomInfo(roomId);
  if (!room) throw new Error('无法获取斗鱼房间信息：' + roomId);
  const normalized = normalizeRoomInfo(room, roomId);
  const isLive = normalized.isLive;
  const resourceVersionPage = await getResourceVersions({ itemId: roomItemId(roomId), title: normalized.title, roomId });
  return {
    pageType: 'detail',
    id: roomItemId(roomId),
    type: 'live',
    title: normalized.title,
    poster: normalized.poster,
    backdrop: normalized.backdrop || normalized.poster,
    detailImageAspectRatio: '16:9',
    imageHeaders: imageHeaders(),
    posterHeaders: imageHeaders(),
    backdropHeaders: imageHeaders(),
    overview: normalized.overview || (normalized.nickname ? ('主播：' + normalized.nickname) : ''),
    genres: ['斗鱼直播'].concat(normalized.category ? [normalized.category] : []),
    cast: normalized.nickname ? [{
      name: normalized.nickname,
      role: isLive ? '主播 · 直播中' : '主播',
      avatar: normalized.avatar,
      avatarHeaders: imageHeaders(),
      action: { type: 'category', pageId: normalized.cate2Id ? ('cate2:' + normalized.cate2Id) : 'recommend', title: normalized.category || '直播间', itemAspectRatio: '16:9' }
    }] : [],
    ratingText: normalized.hotText || '',
    viewCountText: normalized.hotText || '',
    remarks: normalized.statusText,
    providerIds: {
      LiveTitle: normalized.title,
      MiniLibraryPlaybackTitle: playbackTitle(normalized.title)
    },
    resourceGroups: resourceVersionPage.groups || resourceVersionPage
  };
}

async function getResourceVersions(ctx = {}) {
  const roomId = roomIdFromAny(ctx.itemId || ctx.id || ctx.roomId || ctx.url || ctx.href);
  if (!roomId) return { itemId: ctx.itemId || ctx.id || '', groups: [] };
  let room = null;
  try { room = await getRoomInfo(roomId); } catch (_) {}
  const normalized = room ? normalizeRoomInfo(room, roomId) : { title: ctx.title || ('斗鱼房间 ' + roomId), isLive: true };
  const versions = [];
  const rates = await getRateOptions(roomId, normalized.isLive);
  rates.forEach((rate, index) => {
    versions.push({
      id: 'rate:' + rate.rate,
      name: rate.name || (index === 0 ? '原画' : ('线路 ' + (index + 1))),
      subtitle: normalized.statusText || '斗鱼直播',
      container: 'm3u8',
      default: index === 0,
      action: {
        type: 'play',
        itemId: roomItemId(roomId),
        versionId: 'rate:' + rate.rate,
        url: encodePlayPayload({ roomId, rate: rate.rate, title: normalized.title })
      }
    });
  });
  return {
    itemId: roomItemId(roomId),
    groups: [{ id: 'douyu-live', title: '直播清晰度', versions }]
  };
}

async function resolvePlayback(ctx = {}) {
  const config = readConfig(ctx);
  const payload = decodePlayPayload(ctx.url || ctx.playPage || ctx.href || ctx.itemId || ctx.id || '');
  const roomId = String(payload.roomId || roomIdFromAny(ctx.itemId || ctx.id || ctx.url) || '').trim();
  if (!roomId) throw new Error('缺少斗鱼房间 ID');

  const room = await getRoomInfo(roomId);
  const normalized = room ? normalizeRoomInfo(room, roomId) : { title: payload.title || ('斗鱼房间 ' + roomId), isLive: true };
  if (room && !normalized.isLive) {
    throw new Error(normalized.statusText || '该斗鱼房间未开播');
  }

  const signData = payload.signData || await getSignData(roomId);
  if (!signData) throw new Error('斗鱼播放签名生成失败');

  let cdns = payload.cdns || [];
  let rate = Number(payload.rate != null ? payload.rate : rateFromVersionId(ctx.versionId));
  if (!Number.isFinite(rate)) rate = 0;

  if (!cdns.length || payload.rate == null) {
    const probe = await requestPlayInfo(roomId, signData, rate || -1, '', config);
    if (probe && probe.cdns && probe.cdns.length) cdns = probe.cdns;
    if (payload.rate == null && probe && probe.rates && probe.rates.length) {
      const firstRate = probe.rates[0];
      rate = Number(firstRate.rate || 0);
    }
  }

  const candidates = uniqueArray(cdns).concat(['']);
  let selected = null;
  for (let i = 0; i < candidates.length; i++) {
    selected = await getPlayURL(roomId, signData, rate, candidates[i], config);
    if (selected && (selected.hlsUrl || selected.flvUrl)) break;
  }
  if (!selected || (!selected.hlsUrl && !selected.flvUrl)) {
    throw new Error('没有解析到斗鱼播放地址');
  }

  const preferFLV = config.preferFormat === 'flv';
  const playURL = preferFLV ? (selected.flvUrl || selected.hlsUrl) : (selected.hlsUrl || selected.flvUrl);
  return {
    url: playURL,
    container: containerFromURL(playURL),
    headers: playbackHeaders(roomId),
    isLive: true,
    streamKind: 'live',
    title: playbackTitle(normalized.title)
  };
}

function categoryEntry(category, index) {
  const title = String(category.cate1Name || category.title || '直播分区');
  const previewItems = previewSubCategories(category).slice(0, 4).map((item, idx) => ({
    id: 'douyu:preview:' + item.cate2Id,
    title: item.cate2Name || title,
    subtitle: title,
    type: 'collection',
    poster: imageURL(item.pic || item.icon || item.smallIcon),
    backdrop: imageURL(item.pic || item.icon || item.smallIcon),
    aspectRatio: '16:9',
    imageHeaders: imageHeaders(),
    imageFit: 'fill',
    action: { type: 'category', pageId: 'cate2:' + item.cate2Id, title: item.cate2Name || title, itemAspectRatio: '16:9' }
  }));
  return {
    id: 'douyu:cate1:' + category.cate1Id,
    title,
    subtitle: '斗鱼一级分区',
    type: 'collection',
    poster: previewItems[0] ? previewItems[0].poster : PLACEHOLDER_IMAGE,
    backdrop: previewItems[0] ? previewItems[0].backdrop : PLACEHOLDER_IMAGE,
    overview: '浏览斗鱼「' + title + '」分区下的直播内容。',
    rank: index + 1,
    aspectRatio: '16:9',
    imageFit: previewItems[0] ? 'fill' : 'fit',
    imageHeaders: imageHeaders(),
    badges: ['分区'],
    previewItems,
    action: { type: 'category', pageId: 'cate1:' + category.cate1Id, title, itemAspectRatio: '16:9' }
  };
}

function subCategoryEntry(category, index) {
  const title = String(category.cate2Name || category.title || '直播分区');
  return {
    id: 'douyu:cate2:' + category.cate2Id,
    title,
    subtitle: category.count ? (category.count + ' 个直播间') : '斗鱼二级分区',
    type: 'collection',
    poster: imageURL(category.pic || category.icon || category.smallIcon),
    backdrop: imageURL(category.pic || category.icon || category.smallIcon),
    overview: '浏览斗鱼「' + title + '」分区下的直播间。',
    rank: index + 1,
    aspectRatio: '16:9',
    imageFit: category.pic || category.icon ? 'fill' : 'fit',
    imageHeaders: imageHeaders(),
    badges: ['分区'],
    action: { type: 'category', pageId: 'cate2:' + category.cate2Id, title, itemAspectRatio: '16:9' }
  };
}

function roomItem(room, index) {
  const normalized = normalizeListRoom(room);
  const id = roomItemId(normalized.roomId);
  const title = normalized.title || ('斗鱼房间 ' + normalized.roomId);
  const subtitle = compactJoin([normalized.nickname, normalized.category, normalized.hotText], ' · ');
  const statusText = normalized.statusText || '直播中';
  return {
    id,
    title,
    subtitle,
    type: 'live',
    poster: normalized.poster || PLACEHOLDER_IMAGE,
    backdrop: normalized.backdrop || normalized.poster || PLACEHOLDER_IMAGE,
    overview: normalized.overview || subtitle,
    rank: index + 1,
    remarks: statusText,
    metadataText: normalized.hotText || normalized.nickname || '',
    badges: compactArray(['斗鱼', statusText, normalized.category]),
    aspectRatio: '16:9',
    imageFit: normalized.poster ? 'fill' : 'fit',
    imageHeaders: imageHeaders(),
    posterHeaders: imageHeaders(),
    backdropHeaders: imageHeaders(),
    providerIds: {
      LiveTitle: playbackTitle(title),
      MiniLibraryPlaybackTitle: playbackTitle(title),
      DouyuRoomId: normalized.roomId
    },
    action: {
      type: 'play',
      itemId: id,
      title: playbackTitle(title)
    }
  };
}

async function loadCategories() {
  const cached = cacheGet(CATEGORY_CACHE_KEY);
  if (cached && cached.time && Date.now() - Number(cached.time) < CACHE_TTL_MS && cached.data) {
    return cached.data;
  }
  const data = await requestJSON('https://m.douyu.com/api/cate/list', {
    headers: defaultHeaders('https://m.douyu.com/')
  });
  const result = {
    cate1Info: ((((data || {}).data || {}).cate1Info) || DEFAULT_HOME_CATEGORIES).map((item) => Object.assign({}, item)),
    cate2Info: ((((data || {}).data || {}).cate2Info) || []).map((item) => Object.assign({}, item))
  };
  cacheSet(CATEGORY_CACHE_KEY, { time: Date.now(), data: result });
  return result;
}

async function findCate1(cate1Id) {
  const categories = await loadCategories();
  return categories.cate1Info.find((item) => String(item.cate1Id) === String(cate1Id)) || { cate1Id, cate1Name: '直播' };
}

async function firstSubCategory(cate1Id) {
  const categories = await loadCategories();
  return categories.cate2Info.find((item) => String(item.cate1Id) === String(cate1Id));
}

function previewSubCategories(category) {
  if (!category || !category.cate1Id) return [];
  const cached = cacheGet(CATEGORY_CACHE_KEY);
  const data = cached && cached.data;
  const list = data && data.cate2Info ? data.cate2Info : [];
  return list.filter((item) => String(item.cate1Id) === String(category.cate1Id));
}

async function fetchRoomsByCate2(cate2Id, page, limit) {
  const url = 'https://www.douyu.com/gapi/rkc/directory/mixList/2_' + encodeURIComponent(cate2Id) + '/' + Math.max(1, Number(page || 1));
  const data = await requestJSON(url, { headers: defaultHeaders('https://www.douyu.com/directory/game/' + cate2Id) });
  let rooms = ((((data || {}).data || {}).rl) || []).filter((item) => Number(item.type || 1) === 1);
  if (limit) rooms = rooms.slice(0, limit);
  return rooms;
}

async function fetchRecommendRooms(page, limit) {
  const url = 'https://www.douyu.com/japi/weblist/apinc/allpage/6/' + Math.max(1, Number(page || 1));
  const data = await requestJSON(url, { headers: defaultHeaders('https://www.douyu.com/directory/all') });
  let rooms = ((((data || {}).data || {}).rl) || []).filter((item) => Number(item.type || 1) === 1);
  if (limit) rooms = rooms.slice(0, limit);
  return rooms;
}

async function getRoomInfo(roomId) {
  const data = await requestJSON('https://www.douyu.com/betard/' + encodeURIComponent(roomId), {
    headers: defaultHeaders('https://www.douyu.com/' + roomId)
  });
  return data && data.room ? data.room : null;
}

async function getEncryptJS(roomId) {
  const data = await requestJSON('https://www.douyu.com/swf_api/homeH5Enc?rids=' + encodeURIComponent(roomId), {
    headers: defaultHeaders('https://www.douyu.com/' + roomId)
  });
  return data && data.data ? data.data['room' + roomId] : null;
}

async function getSignData(roomId) {
  const encryptedJS = await getEncryptJS(roomId);
  if (!encryptedJS) return '';
  return getDouyuSign(encryptedJS, roomId);
}

function getDouyuSign(script, roomId) {
  try {
    const CryptoJS = {
      MD5: function(value) {
        return { toString: function() { return md5(String(value)); } };
      }
    };
    const time = Math.round(Date.now() / 1000);
    const runner = new Function('CryptoJS', script + '\nreturn typeof ub98484234 === "function" ? ub98484234 : null;');
    const signer = runner(CryptoJS);
    if (typeof signer !== 'function') return '';
    return signer(String(roomId), DOUYU_DID, time);
  } catch (error) {
    log('Douyu sign failed: ' + errorMessage(error));
    return '';
  }
}

async function getRateOptions(roomId, isLive) {
  if (!isLive) return [];
  const signData = await getSignData(roomId);
  if (!signData) return [{ name: '原画', rate: 0 }];
  const data = await requestPlayInfo(roomId, signData, -1, '', { hevc: false });
  const rates = data && data.rates && data.rates.length ? data.rates : [];
  if (!rates.length) return [{ name: '原画', rate: 0 }];
  return rates.map((item, index) => ({
    name: String(item.name || (index === 0 ? '原画' : ('清晰度 ' + (index + 1)))),
    rate: Number(item.rate || 0)
  }));
}

async function requestPlayInfo(roomId, signData, rate, cdn, config) {
  const body = signData + '&cdn=' + encodeURIComponent(cdn || '')
    + '&rate=' + encodeURIComponent(String(rate == null ? 0 : rate))
    + '&ver=Douyu_223061205&iar=1&ive=1&hevc=' + (config && config.hevc ? '1' : '0') + '&fa=0';
  const result = await requestJSON('https://www.douyu.com/lapi/live/getH5Play/' + encodeURIComponent(roomId), {
    method: 'POST',
    body,
    headers: Object.assign({}, defaultHeaders('https://www.douyu.com/' + roomId), {
      'Content-Type': 'application/x-www-form-urlencoded'
    })
  });
  const data = result && result.data ? result.data : null;
  if (!data) return null;
  return {
    raw: data,
    cdns: (data.cdnsWithName || []).map((item) => String(item.cdn || '')).filter(Boolean).sort((a, b) => {
      const aSlow = a.indexOf('scdn') === 0 ? 1 : 0;
      const bSlow = b.indexOf('scdn') === 0 ? 1 : 0;
      return aSlow - bSlow;
    }),
    rates: data.multirates || []
  };
}

async function getPlayURL(roomId, signData, rate, cdn, config) {
  const info = await requestPlayInfo(roomId, signData, rate, cdn, config);
  const data = info && info.raw;
  if (!data || !data.rtmp_url || !data.rtmp_live) return null;
  const rtmpURL = String(data.rtmp_url || '');
  const rtmpLive = htmlUnescape(String(data.rtmp_live || ''));
  const flvUrl = rtmpURL && rtmpLive ? (rtmpURL + '/' + rtmpLive) : '';
  let hlsUrl = '';
  if (data.hls_url && data.hls_live) {
    hlsUrl = String(data.hls_url) + '/' + htmlUnescape(String(data.hls_live));
  }
  return { hlsUrl, flvUrl };
}

function normalizeListRoom(item) {
  const roomId = String(item.rid || item.roomId || item.room_id || item.id || '');
  const title = htmlUnescape(String(item.rn || item.roomName || item.room_name || item.title || ''));
  const nickname = htmlUnescape(String(item.nn || item.nickName || item.owner_name || item.nickname || ''));
  const poster = imageURL(item.rs16 || item.roomSrc || item.room_pic || item.pic || item.rs1 || item.avatar || '');
  const category = htmlUnescape(String(item.c2name || item.cate2Name || item.c2name_display || item.game_name || ''));
  const hot = item.ol || item.hn || item.hot || item.online || '';
  return {
    roomId,
    title,
    nickname,
    poster,
    backdrop: poster,
    category,
    cate2Id: item.cid2 || item.cate2Id,
    hotText: hot ? formatHot(hot) : '',
    statusText: '直播中',
    isLive: true
  };
}

function normalizeSearchRoom(item) {
  return {
    rid: item.rid,
    rn: item.roomName,
    nn: item.nickName,
    rs16: item.roomSrc,
    c2name: item.cate2Name || item.gameName,
    ol: item.hot || item.online
  };
}

function normalizeRoomInfo(room, fallbackRoomId) {
  const roomId = String(room.room_id || room.rid || fallbackRoomId || '');
  const title = htmlUnescape(String(room.room_name || room.rn || '斗鱼房间 ' + roomId));
  const nickname = htmlUnescape(String(room.owner_name || room.nn || ''));
  const poster = imageURL(room.room_pic || room.rs16 || room.roomSrc || '');
  const avatar = imageURL(room.owner_avatar || room.avatar || '');
  const category = htmlUnescape(String(room.cate2_name || room.game_name || room.c2name || ''));
  const isRecord = Number(room.videoLoop || 0) === 1;
  const isLive = Number(room.show_status || room.showStatus || 0) === 1 && !isRecord;
  return {
    roomId,
    title,
    nickname,
    poster: poster || avatar || PLACEHOLDER_IMAGE,
    backdrop: poster || PLACEHOLDER_IMAGE,
    avatar,
    overview: htmlUnescape(stripHTML(String(room.show_details || room.description || ''))),
    category,
    cate2Id: room.cate2_id || room.cate2Id || room.cid2,
    isLive,
    statusText: isLive ? '直播中' : (isRecord ? '录播中' : '未开播'),
    hotText: room.online ? formatHot(room.online) : ''
  };
}

function requestJSON(url, options) {
  const text = requestText(url, options || {});
  if (typeof text === 'object') return text;
  try { return JSON.parse(text); } catch (error) {
    throw new Error('斗鱼接口返回不是 JSON：' + String(text || '').slice(0, 120));
  }
}

function requestText(url, options) {
  options = options || {};
  const method = String(options.method || 'GET').toUpperCase();
  const headers = Object.assign({}, defaultHeaders(url), options.headers || {});
  if (typeof Widget !== 'undefined' && Widget.http) {
    const response = method === 'POST' && typeof Widget.http.post === 'function'
      ? Widget.http.post(url, options.body || '', { headers, timeout: options.timeout || 12 })
      : Widget.http.get(url, { headers, timeout: options.timeout || 12 });
    const data = response && response.data;
    if (typeof data === 'string') return data;
    if (data == null) return '';
    return JSON.stringify(data);
  }
  if (typeof fetch === 'function') {
    const init = { method, headers };
    if (method === 'POST') init.body = options.body || '';
    const childProcess = typeof require === 'function' ? null : null;
  }
  throw new Error('当前小程序环境缺少 Widget.http');
}

function defaultHeaders(referer) {
  return {
    'User-Agent': PC_UA,
    Referer: referer || WidgetMetadata.site
  };
}

function imageHeaders() {
  return {
    Referer: WidgetMetadata.site,
    'User-Agent': MOBILE_UA
  };
}

function playbackHeaders(roomId) {
  return {
    Referer: 'https://www.douyu.com/' + roomId,
    'User-Agent': PC_UA
  };
}

function encodePlayPayload(payload) {
  return 'douyu:' + base64Encode(JSON.stringify(payload || {}));
}

function decodePlayPayload(value) {
  const text = String(value || '');
  if (text.indexOf('douyu:') === 0) {
    try { return JSON.parse(base64Decode(text.slice('douyu:'.length))) || {}; } catch (_) { return {}; }
  }
  return { roomId: roomIdFromAny(text) };
}

function roomItemId(roomId) {
  return 'douyu:room:' + roomId;
}

function roomIdFromAny(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  if (text.indexOf('douyu:room:') === 0) return text.slice('douyu:room:'.length);
  if (text.indexOf('douyu:') === 0) {
    const payload = decodePlayPayload(text);
    if (payload.roomId) return String(payload.roomId);
  }
  const match = text.match(/(?:douyu\.com\/|room[:=]|rid[:=])([0-9]+)/i) || text.match(/^([0-9]+)$/);
  return match ? match[1] : '';
}

function rateFromVersionId(versionId) {
  const match = String(versionId || '').match(/rate:([\-0-9]+)/);
  return match ? Number(match[1]) : 0;
}

function containerFromURL(url) {
  const clean = String(url || '').split('?')[0].toLowerCase();
  if (clean.indexOf('.m3u8') >= 0) return 'm3u8';
  if (clean.indexOf('.flv') >= 0) return 'flv';
  if (clean.indexOf('.xs') >= 0) return 'flv';
  const ext = clean.match(/\.([a-z0-9]+)$/);
  return ext ? ext[1] : 'm3u8';
}

function imageURL(value) {
  const url = String(value || '').trim();
  if (!url) return '';
  if (url.indexOf('//') === 0) return 'https:' + url;
  if (/^https?:\/\//i.test(url) || url.indexOf('data:image/') === 0) return url;
  if (url.indexOf('/') === 0) return 'https://www.douyu.com' + url;
  return url;
}

function playbackTitle(title) {
  return String(title || '').replace(/\s*[（(].*?[）)]\s*$/g, '').trim() || String(title || '斗鱼直播');
}

function md5(value) {
  if (typeof $crypto !== 'undefined' && $crypto.md5) return $crypto.md5(String(value));
  if (typeof Widget !== 'undefined' && Widget.crypto && Widget.crypto.md5) return Widget.crypto.md5(String(value));
  if (typeof require === 'function') return require('crypto').createHash('md5').update(String(value)).digest('hex');
  throw new Error('当前小程序环境缺少 MD5 能力');
}

function base64Encode(text) {
  if (typeof $utils !== 'undefined' && $utils.base64Encode) return $utils.base64Encode(String(text));
  if (typeof btoa === 'function') return btoa(String(text));
  if (typeof Buffer !== 'undefined') return Buffer.from(String(text), 'utf8').toString('base64');
  throw new Error('当前小程序环境缺少 base64Encode 能力');
}

function base64Decode(text) {
  if (typeof $utils !== 'undefined' && $utils.base64Decode) return $utils.base64Decode(String(text));
  if (typeof atob === 'function') return atob(String(text));
  if (typeof Buffer !== 'undefined') return Buffer.from(String(text), 'base64').toString('utf8');
  throw new Error('当前小程序环境缺少 base64Decode 能力');
}

function cacheGet(key) {
  if (typeof Widget !== 'undefined' && Widget.storage && Widget.storage.get) return Widget.storage.get(key);
  if (typeof $cache !== 'undefined' && $cache.get) {
    const value = $cache.get(key);
    if (typeof value === 'string') { try { return JSON.parse(value); } catch (_) {} }
    return value;
  }
  return null;
}

function cacheSet(key, value) {
  if (typeof Widget !== 'undefined' && Widget.storage && Widget.storage.set) return Widget.storage.set(key, value);
  if (typeof $cache !== 'undefined' && $cache.set) return $cache.set(key, JSON.stringify(value));
}

function argsify(ctx) {
  if (!ctx) return {};
  if (typeof ctx === 'string') { try { return JSON.parse(ctx); } catch (_) { return { raw: ctx }; } }
  return ctx;
}

function parseBool(value) {
  if (typeof value === 'boolean') return value;
  const text = String(value == null ? '' : value).trim().toLowerCase();
  return text === '1' || text === 'true' || text === 'yes' || text === 'on';
}

function clampNumber(value, min, max, fallback) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(min, Math.min(max, Math.round(number)));
}

function formatHot(value) {
  if (value == null || value === '') return '';
  const raw = String(value);
  if (raw.indexOf('万') >= 0) return raw;
  const number = Number(raw);
  if (!Number.isFinite(number)) return raw;
  if (number >= 10000) return (number / 10000).toFixed(number >= 100000 ? 0 : 1).replace(/\.0$/, '') + '万热度';
  return Math.round(number) + '热度';
}

function htmlUnescape(str) {
  return String(str || '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'")
    .replace(/&#x2F;/g, '/');
}

function stripHTML(value) {
  return String(value || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function compactArray(items) {
  return (items || []).map((item) => String(item || '').trim()).filter(Boolean);
}

function compactJoin(items, separator) {
  return compactArray(items).join(separator || ' · ');
}

function uniqueArray(items) {
  const seen = {};
  const result = [];
  (items || []).forEach((item) => {
    const value = String(item || '').trim();
    if (!value || seen[value]) return;
    seen[value] = true;
    result.push(value);
  });
  return result;
}

function randomHex(length) {
  const chars = '0123456789abcdef';
  let result = '';
  for (let i = 0; i < length; i++) result += chars.charAt(Math.floor(Math.random() * 16));
  return result;
}

function errorMessage(error) {
  return error && error.message ? error.message : String(error || '未知错误');
}

function log(value) {
  if (typeof console !== 'undefined' && console.log) console.log(String(value));
}

const exported = {
  WidgetMetadata,
  getManifest,
  getHome,
  getHomeSection,
  getCategory,
  getDetail,
  getResourceVersions,
  resolvePlayback,
  search,
  home: getHome,
  homeSection: getHomeSection,
  category: getCategory,
  detail: getDetail,
  getVersions: getResourceVersions,
  resolvePlay: resolvePlayback,
  play: resolvePlayback,
  quickSearch: search
};

if (typeof module !== 'undefined') module.exports = exported;
if (typeof globalThis !== 'undefined') Object.assign(globalThis, exported);
